<?php get_header(); ?><div class="wrap layout"><main id="main"><?php while(have_posts()): the_post(); ?><article id="post-<?php the_ID(); ?>" <?php post_class(); ?>><header class="post-header"><?php allge_categories(); ?><h1><?php the_title(); ?></h1><div class="post-meta">Por <?php the_author_posts_link(); ?> &middot; <time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date()); ?></time> &middot; <?php echo esc_html(max(1,(int)ceil(str_word_count(wp_strip_all_tags(get_the_content()))/200))); ?> min de leitura</div></header><?php if(has_post_thumbnail()): the_post_thumbnail('large',array('class'=>'post-cover','loading'=>'eager','fetchpriority'=>'high','decoding'=>'async','sizes'=>'(max-width: 600px) calc(100vw - 32px), (max-width: 900px) calc(100vw - 40px), (max-width: 1240px) calc(100vw - 388px), 852px')); endif; ?><div class="entry-content"><?php the_content(); wp_link_pages(array('before'=>'<nav aria-label="Páginas do artigo">','after'=>'</nav>')); ?></div><?php allge_share_buttons(); the_tags('<div class="post-tags">Tags: ',', ','</div>'); ?><section class="author-box"><?php echo get_avatar(get_the_author_meta('ID'),64); ?><div><h2><?php the_author_posts_link(); ?></h2><p><?php echo esc_html(get_the_author_meta('description')); ?></p></div></section></article><?php if(is_active_sidebar('ad-article')): ?><div class="ad"><?php dynamic_sidebar('ad-article'); ?></div><?php endif; the_post_navigation(array('prev_text'=>'← %title','next_text'=>'%title →')); if(comments_open() || get_comments_number()): comments_template(); endif; endwhile; ?></main><?php get_sidebar(); ?></div><?php get_footer(); ?>
